import { Component, Input } from '@angular/core';
import { TotalStats } from '../../models/health-data.model';

@Component({
  selector: 'app-weekly-progress',
  templateUrl: './weekly-progress.component.html',
  styleUrls: ['./weekly-progress.component.scss']
})
export class WeeklyProgressComponent {
  @Input() totalStats: TotalStats | null = null;

  formatValue(value: number): string {
    return value.toLocaleString();
  }

  roundValue(value: number): number {
    return Math.round(value);
  }
}
<div class="grid grid-cols-2 gap-4">
  <div class="bg-white/20 backdrop-blur-sm rounded-xl p-4 text-center shadow-lg border border-white/30">
    <div class="text-2xl font-bold text-white mb-1">{{ formatValue(weeklyStats?.totalSteps || 0) }}</div>
    <div class="text-sm text-white/80">Total Steps</div>
  </div>
  <div class="bg-white/20 backdrop-blur-sm rounded-xl p-4 text-center shadow-lg border border-white/30">
    <div class="text-2xl font-bold text-white mb-1">{{ formatValue(weeklyStats?.totalCalories || 0) }}</div>
    <div class="text-sm text-white/80">Total Calories</div>
  </div>
  <div class="bg-white/20 backdrop-blur-sm rounded-xl p-4 text-center shadow-lg border border-white/30">
    <div class="text-2xl font-bold text-white mb-1">{{ weeklyStats?.daysTracked || 0 }}</div>
    <div class="text-sm text-white/80">Days Tracked</div>
  </div>
  <div class="bg-white/20 backdrop-blur-sm rounded-xl p-4 text-center shadow-lg border border-white/30">
    <div class="text-2xl font-bold text-white mb-1">{{ formatValue((weeklyStats?.totalSteps || 0) / (weeklyStats?.daysTracked || 1)) }}</div>
    <div class="text-sm text-white/80">Avg Steps/Day</div>
  </div>
</div>
